function solve(index, currentSum, lastOperand, path) {
  if (index === num.length) {
    if (currentSum === target) res.push(path);
    return;
  }
  for (let i = index; i < num.length; i++) {
    let val = parseInt(num.substring(index, i + 1));
    if (index === 0) solve(i + 1, val, val, val.toString());
    else {
      solve(i + 1, currentSum + val, val, path + '+' + val);
      solve(i + 1, currentSum - val, -val, path + '-' + val);
      solve(i + 1, currentSum - lastOperand + lastOperand * val, lastOperand * val, path + '*' + val);
    }
    if (num[index] === '0') break;
  }
}
